export interface RiskScoreConfig {
  tier: "LOW" | "MEDIUM" | "HIGH";
  textColor: string;
  borderColor: string;
  borderHover: string;
  badgeBg: string;
  badgeText: string;
  glow: string;
  hex: string;
  barColor: string;
}

export function getRiskScoreConfig(score: number): RiskScoreConfig {
  if (score <= 15) {
    return {
      tier: "LOW",
      textColor: "text-emerald-400",
      borderColor: "border-emerald-500/40",
      borderHover: "hover:border-emerald-400/80",
      badgeBg: "bg-emerald-950/50",
      badgeText: "text-emerald-300",
      glow: "shadow-[0_0_20px_rgba(16,185,129,0.22)]",
      hex: "#10b981",
      barColor: "bg-emerald-400",
    };
  } else if (score <= 35) {
    return {
      tier: "MEDIUM",
      textColor: "text-amber-400",
      borderColor: "border-amber-500/40",
      borderHover: "hover:border-amber-400/80",
      badgeBg: "bg-amber-950/50",
      badgeText: "text-amber-300",
      glow: "shadow-[0_0_20px_rgba(245,158,11,0.22)]",
      hex: "#f59e0b",
      barColor: "bg-amber-400",
    };
  } else {
    return {
      tier: "HIGH",
      textColor: "text-rose-400",
      borderColor: "border-rose-500/40",
      borderHover: "hover:border-rose-400/80",
      badgeBg: "bg-rose-950/50",
      badgeText: "text-rose-300",
      glow: "shadow-[0_0_20px_rgba(244,63,94,0.22)]",
      hex: "#f43f5e",
      barColor: "bg-rose-400",
    };
  }
}

